window.__code__["code-w01-sse-handwrite-py"] = {"code_id": "code-w01-sse-handwrite-py", "kind": "local", "title": "sse_handwrite.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w01/sse_handwrite.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w01/sse_handwrite.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W01 作业1:用 httpx 直接调 DashScope OpenAI兼容接口,手写 SSE 字节流解析</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 体会:LLM 流式就是 HTTP 长连接上一条条 data: {...} 块,要自己拼缓冲区</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w01/sse_handwrite.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  模型解释协程的三句话逐字流式出现,最后打印 [DONE]</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> json</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">import</span> httpx  <span class=\"c-com\"># 你可能需要: uv pip install httpx</span></span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">DASHSCOPE_URL = <span class=\"c-str\">&quot;https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> stream_chat(prompt: str) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">    headers = {</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">        <span class=\"c-str\">&quot;Authorization&quot;</span>: f<span class=\"c-str\">&quot;Bearer {os.environ[&#x27;DASHSCOPE_API_KEY&#x27;]}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">        <span class=\"c-str\">&quot;Content-Type&quot;</span>: <span class=\"c-str\">&quot;application/json&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    }</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">    payload = {</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">        <span class=\"c-str\">&quot;model&quot;</span>: <span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">        <span class=\"c-str\">&quot;messages&quot;</span>: [{<span class=\"c-str\">&quot;role&quot;</span>: <span class=\"c-str\">&quot;user&quot;</span>, <span class=\"c-str\">&quot;content&quot;</span>: prompt}],</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">        <span class=\"c-str\">&quot;stream&quot;</span>: <span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">        <span class=\"c-str\">&quot;stream_options&quot;</span>: {<span class=\"c-str\">&quot;include_usage&quot;</span>: <span class=\"c-kw\">True</span>},</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    }</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    <span class=\"c-com\"># async with:上下文管理,离开块自动关连接</span></span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> httpx.AsyncClient(timeout=60) <span class=\"c-kw\">as</span> client:</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> client.stream(<span class=\"c-str\">&quot;POST&quot;</span>, DASHSCOPE_URL, headers=headers, json=payload) <span class=\"c-kw\">as</span> resp:</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">            resp.raise_for_status()</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">            buf = <span class=\"c-str\">&quot;&quot;</span>  <span class=\"c-com\"># 缓冲区:处理\u000027\u0000(字节流可能在 JSON 中间被切断)</span></span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> raw <span class=\"c-kw\">in</span> resp.aiter_text():</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">                buf += raw</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">                <span class=\"c-com\"># SSE 以两个换行分隔每条事件</span></span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">                <span class=\"c-kw\">while</span> <span class=\"c-str\">&quot;\\n\\n&quot;</span> <span class=\"c-kw\">in</span> buf:</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">                    chunk, buf = buf.split(<span class=\"c-str\">&quot;\\n\\n&quot;</span>, 1)</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">                    <span class=\"c-kw\">for</span> line <span class=\"c-kw\">in</span> chunk.splitlines():</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">                        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> line.startswith(<span class=\"c-str\">&quot;data:&quot;</span>):</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">                            <span class=\"c-kw\">continue</span></span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">                        data = line[len(<span class=\"c-str\">&quot;data:&quot;</span>):].strip()</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">                        <span class=\"c-kw\">if</span> data == <span class=\"c-str\">&quot;[DONE]&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">                            print(<span class=\"c-str\">&quot;\\n[DONE]&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">                            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">                        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">                            delta = json.loads(data)[<span class=\"c-str\">&quot;choices&quot;</span>][0].get(<span class=\"c-str\">&quot;delta&quot;</span>, {})</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">                        <span class=\"c-kw\">except</span> (json.JSONDecodeError, KeyError):</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">                            <span class=\"c-kw\">continue</span></span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">                        <span class=\"c-kw\">if</span> <span class=\"c-str\">&quot;content&quot;</span> <span class=\"c-kw\">in</span> delta:</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">                            print(delta[<span class=\"c-str\">&quot;content&quot;</span>], end=<span class=\"c-str\">&quot;&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    <span class=\"c-kw\">await</span> stream_chat(<span class=\"c-str\">&quot;用三句话向我解释什么是协程。&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 60, "explanation": "sse_handwrite.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W01-Python异步与LLM-API调用"]};
